def hanja_plain_replace(text: str) -> str:
    """출력 텍스트에서 한자 용어를 쉬운 한글 풀이로 자동 변환"""
    if not text:
        return text
    # 1단계: 구체적인 구문 패턴 먼저 교체
    for pattern, replacement in _SS_PHRASE_MAP:
        text = re.sub(pattern, replacement, text)
    # 2단계: {한글}({한자}) → {한글} (괄호 한자 제거)
    text = re.sub(r'([가-힣]+)\(([A-Z\u4e00-\u9fff]+)\)', r'\1', text)
    # 3단계: 독립 한자어 → 한글
    for hanja, kr in _HANJA_WORD_KR.items():
        text = text.replace(hanja, kr)
    return text


