                    _sw_pa = get_yearly_luck(pils, _yr_pa) or {}
                    _jj_pa = _sw_pa.get("jj","")
                    _cg_pa = _sw_pa.get("세운","")[:1] if _sw_pa.get("세운") else ""
                    _ss_pa = _sw_pa.get("십성_천간","")
