        lines = []
        lines.append(f"## 📆 {name}님의 향후 6개월 정밀 월별 다이어리")
        lines.append(
            f"*올해 세운: {sw.get('세운','')} [{_SS_KR.get(sw_ss, sw_ss)}] {sw.get('길흉','평')}*\n"
        )

