def get_yukjin(ilgan, pils, gender="남", marriage="미혼"):


    ss_to_family = {
        '比肩(비견)': '형제·자매·친구',
        '劫財(겁재)': '형제·자매·경쟁자',
        '食神(식신)': '자녀·제자',
        '傷官(상관)': '자녀·제자',
        '偏財(편재)': '아버지·애인',
        '正財(정재)': '아버지·배우자',
        '偏官(편관)': '자녀(남)·직장상사',
        '正官(정관)': '남편·직장',
        '偏印(편인)': '어머니·이모',
        '正印(정인)': '어머니·윗사람',
    }

    sipsung_data = calc_sipsung(ilgan, pils)

    found = {}

    for i, ss_info in enumerate(sipsung_data):
        label = ["시주", "일주", "월주", "년주"][i]

        p = pils[i]

        for ss in [ss_info.get("cg_ss", "-"), ss_info.get("jj_ss", "-")]:
            fam = ss_to_family.get(ss)

            if fam:
                if fam not in found:
                    found[fam] = []

                found[fam].append(f"{label}({p.get('cg','')}{p.get('jj','')})")

    result = []

    checks = [
        (
            "어머니(正印)",
            "정인",
            "인성이 있어 어머니의 음덕(蔭德)이 큽니다.",
            "정인(어머니 기운)이 약합니다. 어머니와의 인연이 엷거나 일찍 독립하는 기운입니다.",
        ),
        (
            "아버지(偏財)",
            "편재",
            "편재(아버지 기운)가 있습니다. 아버지의 재물적 도움이 있거나 부친 덕이 있습니다.",
            "편재(아버지 기운)가 약합니다. 부친과의 인연이 엷거나 일찍 독립하는 기운입니다.",
        ),
    ]

    if _normalize_gender(gender):
        checks += [
            (
                "아내(正財)",
                "정재",
                "정재(아내 기운)가 있습니다. 배우자 인연이 있고 가정적인 아내를 만날 기운입니다.",
                "정재(아내 기운)가 약합니다. 결혼이 늦거나 대운에서 재성운이 올 때 인연이 찾아옵니다.",
            ),
            (
                "아들(偏官)/딸(正官)",
                "편관",
                "관살이 있습니다. 자녀 인연이 있으며 자녀로 인한 기쁨이 있습니다.",
                "관살이 약합니다. 자녀와의 인연이 엷거나 늦게 생길 수 있습니다.",
            ),
        ]

    else:
        checks += [
            (
                "남편(正官)",
                "정관",
                "정관(남편 기운)이 있습니다. 안정적이고 믿음직하며 사회적으로 인정받는 남편 인연입니다. 공직·조직에서 일하는 안정적인 파트너와 인연이 깊습니다.",
                "정관(남편 기운)이 원국에 드러나지 않습니다. 이는 남편이 없다는 의미가 아니라, 남편과의 인연이 대운이나 세운에서 들어오는 구조이거나 편관으로 대체되는 형태입니다. 원국에 없어도 현실에서 결혼한 분들이 많으며, 오히려 남편에 대한 의존도가 낮고 독립적으로 생활하는 경향을 나타냅니다.",
            ),
            (
                "아들(食神)/딸(傷官)",
                "식신",
                "식상이 있습니다. 자녀 인연이 있으며 자녀로 인한 기쁨이 있습니다. 자녀를 통해 삶이 풍요로워지는 구조입니다.",
                "식상이 원국에 드러나지 않습니다. 이는 자녀가 없다는 의미가 아니라 자녀 인연이 대운에서 들어오거나, 자녀에 대한 의존보다 자신의 독립적 삶을 중시하는 성향을 나타냅니다. 현실에서 자녀가 있어도 이 배치인 경우가 많습니다.",
            ),
        ]

    checks.append(
        (
            "형제(比肩)",
            "비견",
            "비겁이 있습니다. 형제자매 또는 동료/친구와의 인연이 깊습니다.",
            "비겁이 약합니다. 형제자매 인연이 엷거나 자립심이 강한 독립적인 기질입니다.",
        )
    )

    sipsung_all = [ss for si in sipsung_data for ss in [si.get("cg_ss", "-"), si.get("jj_ss", "-")]]

    for fam_label, ss_key, yes_msg, no_msg in checks:
        has = ss_key in sipsung_all
        where = ", ".join(found.get(fam_label, []))

        # 기혼인데 배우자성 없음 → 별도 처리
        _is_married = marriage in ("기혼","유부남","유부녀","이혼","이혼/별거","이혼/사별","사별","재혼")
        _is_spouse = any(k in fam_label for k in ["남편","아내","배우자"])
        if not has and _is_married and _is_spouse:
            _adj_msg = (no_msg.split(". ")[0] +
                f". 현재 결혼 상태이므로 배우자 인연은 대운·세운을 통해 이루어진 것입니다. "
                f"원국에 드러나지 않는다는 것은 배우자와의 관계가 조용하고 내조형이거나, "
                f"배우자에게 크게 의존하지 않는 독립적 성향을 나타냅니다.")
        else:
            _adj_msg = yes_msg if has else no_msg

        result.append(
            {
                "관계": fam_label,
                "위치": where if where else "없음",
                "present": has,
                "desc": _adj_msg,
            }
        )

    return result


